class Solution:
    def evaluate(self, expression: str) -> int:
        scopes = [{}]

        def get(var):
            for s in reversed(scopes):
                if var in s:
                    return s[var]
            raise ValueError(var)

        def parse(e):
            if e[0] != '(':
                if e[0].isalpha():
                    return get(e)
                return int(e)
            e = e[1:-1]
            tokens, depth, cur = [], 0, ''
            for ch in e:
                if ch == '(':
                    depth += 1
                elif ch == ')':
                    depth -= 1
                if ch == ' ' and depth == 0:
                    tokens.append(cur)
                    cur = ''
                else:
                    cur += ch
            tokens.append(cur)
            if tokens[0] == 'add':
                return parse(tokens[1]) + parse(tokens[2])
            if tokens[0] == 'mult':
                return parse(tokens[1]) * parse(tokens[2])
            scopes.append({})
            i = 1
            while i + 1 < len(tokens):
                scopes[-1][tokens[i]] = parse(tokens[i + 1])
                i += 2
            res = parse(tokens[-1])
            scopes.pop()
            return res

        return parse(expression)

