class Solution {
public:
    vector<unordered_map<string,int>> scopes;

    int get(const string& var) {
        for (int i = scopes.size() - 1; i >= 0; --i)
            if (scopes[i].count(var)) return scopes[i][var];
        return 0;
    }

    int parse(const string& e) {
        if (e[0] != '(') {
            if (isalpha(e[0])) return get(e);
            return stoi(e);
        }
        vector<string> tokens;
        string cur;
        int depth = 0;
        for (int i = 1; i + 1 < (int)e.size(); ++i) {
            char ch = e[i];
            if (ch == '(') depth++;
            else if (ch == ')') depth--;
            if (ch == ' ' && depth == 0) { tokens.push_back(cur); cur.clear(); }
            else cur += ch;
        }
        tokens.push_back(cur);
        if (tokens[0] == "add") return parse(tokens[1]) + parse(tokens[2]);
        if (tokens[0] == "mult") return parse(tokens[1]) * parse(tokens[2]);
        scopes.push_back({});
        size_t i = 1;
        while (i + 1 < tokens.size()) {
            scopes.back()[tokens[i]] = parse(tokens[i + 1]);
            i += 2;
        }
        int res = parse(tokens.back());
        scopes.pop_back();
        return res;
    }

    int evaluate(string expression) {
        scopes.push_back({});
        return parse(expression);
    }
};

