class Solution {
    private List<Map<String,Integer>> scopes = new ArrayList<>();

    private int get(String var) {
        for (int i = scopes.size() - 1; i >= 0; i--) {
            Integer v = scopes.get(i).get(var);
            if (v != null) return v;
        }
        throw new RuntimeException();
    }

    private int parse(String e) {
        if (e.charAt(0) != '(') {
            if (Character.isLetter(e.charAt(0))) return get(e);
            return Integer.parseInt(e);
        }
        List<String> tokens = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        int depth = 0;
        for (int i = 1; i < e.length() - 1; i++) {
            char ch = e.charAt(i);
            if (ch == '(') depth++;
            else if (ch == ')') depth--;
            if (ch == ' ' && depth == 0) { tokens.add(cur.toString()); cur.setLength(0); }
            else cur.append(ch);
        }
        tokens.add(cur.toString());
        if (tokens.get(0).equals("add")) return parse(tokens.get(1)) + parse(tokens.get(2));
        if (tokens.get(0).equals("mult")) return parse(tokens.get(1)) * parse(tokens.get(2));
        scopes.add(new HashMap<>());
        int i = 1;
        while (i + 1 < tokens.size()) {
            scopes.get(scopes.size() - 1).put(tokens.get(i), parse(tokens.get(i + 1)));
            i += 2;
        }
        int res = parse(tokens.get(tokens.size() - 1));
        scopes.remove(scopes.size() - 1);
        return res;
    }

    public int evaluate(String expression) {
        scopes.add(new HashMap<>());
        return parse(expression);
    }
}

