class Solution:
    def evaluate(self, expression: str) -> int:
        tokens = expression.replace('(', '( ').replace(')', ' )').split()
        pos = 0

        def peek():
            return tokens[pos]

        def parse(scopes):
            nonlocal pos
            tok = tokens[pos]
            if tok != '(':
                pos += 1
                if tok.lstrip('-').isdigit():
                    return int(tok)
                for s in reversed(scopes):
                    if tok in s:
                        return s[tok]
            pos += 1  # consume '('
            op = tokens[pos]; pos += 1
            if op == 'add':
                a = parse(scopes); b = parse(scopes); pos += 1
                return a + b
            if op == 'mult':
                a = parse(scopes); b = parse(scopes); pos += 1
                return a * b
            scopes.append({})
            while tokens[pos] != '(' and not _is_final(pos):
                var = tokens[pos]; pos += 1
                scopes[-1][var] = parse(scopes)
            res = parse(scopes)
            scopes.pop()
            return res

        def _is_final(i):
            # count remaining alternating pairs: final expr is last token before ')'
            j, depth = i, 0
            cnt = 0
            while tokens[j] != ')':
                if tokens[j] == '(':
                    depth += 1
                elif tokens[j] == ')':
                    depth -= 1
                j += 1
            # simpler: walk pairs until only one expression remains
            k = i
            while True:
                nxt = k + 1
                if nxt == len(tokens) or tokens[nxt] == ')':
                    return True
                # skip one expression starting at k
                if tokens[k] == '(':
                    d = 0
                    while True:
                        if tokens[k] == '(': d += 1
                        elif tokens[k] == ')': d -= 1
                        k += 1
                        if d == 0: break
                else:
                    k += 1
                if tokens[k] == ')':
                    return True
                return False

        return parse([{}])

