// Same idea as Approach 1 but consuming a pre-tokenized stream.
class Solution {
public:
    vector<string> toks;
    int pos = 0;

    int parse(vector<unordered_map<string,int>>& sc) {
        string t = toks[pos];
        if (t != "(") {
            pos++;
            if (!isalpha(t[0])) return stoi(t);
            for (int i = sc.size() - 1; i >= 0; --i)
                if (sc[i].count(t)) return sc[i][t];
            return 0;
        }
        pos++;
        string op = toks[pos++];
        if (op == "add") { int a = parse(sc), b = parse(sc); pos++; return a + b; }
        if (op == "mult") { int a = parse(sc), b = parse(sc); pos++; return a * b; }
        sc.push_back({});
        // Determine number of binding pairs by counting expressions until final one.
        // Simpler robust method: bind greedily while the token after the next expression is not ')'.
        auto exprEnd = [&](int start) {
            int d = 0, k = start;
            do {
                if (toks[k] == "(") d++;
                else if (toks[k] == ")") d--;
                k++;
            } while (d > 0);
            return k;
        };
        while (true) {
            int end = (toks[pos] == "(") ? exprEnd(pos) : pos + 1;
            if (end < (int)toks.size() && toks[end] != ")") {
                string var = toks[pos++];
                sc.back()[var] = parse(sc);
            } else break;
        }
        int res = parse(sc);
        sc.pop_back();
        return res;
    }

    int evaluate(string expression) {
        string cur;
        for (char c : expression) {
            if (c == '(' || c == ')') { if (!cur.empty()) toks.push_back(cur); cur.clear(); toks.push_back(string(1,c)); }
            else if (c == ' ') { if (!cur.empty()) toks.push_back(cur); cur.clear(); }
            else cur += c;
        }
        if (!cur.empty()) toks.push_back(cur);
        vector<unordered_map<string,int>> sc(1);
        return parse(sc);
    }
};

