class Solution {
    private String[] toks;
    private int pos;

    private int parse(List<Map<String,Integer>> sc) {
        String t = toks[pos];
        if (!t.equals("(")) {
            pos++;
            if (!Character.isLetter(t.charAt(0))) return Integer.parseInt(t);
            for (int i = sc.size() - 1; i >= 0; i--) {
                Integer v = sc.get(i).get(t);
                if (v != null) return v;
            }
            return 0;
        }
        pos++;
        String op = toks[pos++];
        if (op.equals("add")) { int a = parse(sc), b = parse(sc); pos++; return a + b; }
        if (op.equals("mult")) { int a = parse(sc), b = parse(sc); pos++; return a * b; }
        sc.add(new HashMap<>());
        while (true) {
            int end = toks[pos].equals("(") ? exprEnd(pos) : pos + 1;
            if (end < toks.length && !toks[end].equals(")")) {
                String var = toks[pos++];
                sc.get(sc.size() - 1).put(var, parse(sc));
            } else break;
        }
        int res = parse(sc);
        sc.remove(sc.size() - 1);
        return res;
    }

    private int exprEnd(int start) {
        int d = 0, k = start;
        do {
            if (toks[k].equals("(")) d++;
            else if (toks[k].equals(")")) d--;
            k++;
        } while (d > 0);
        return k;
    }

    public int evaluate(String expression) {
        toks = expression.replace("(", " ( ").replace(")", " ) ").trim().split("\\s+");
        pos = 0;
        return parse(new ArrayList<>(List.of(new HashMap<>())));
    }
}

